Here is the correct `DropSeen` — it drops items already present in the `seen` store and returns the rest.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{feed-item};

    import aap:caps/state-read@0.1.0;

    export run: func(items: list<feed-item>) -> list<feed-item>;
}
